    public static void furnaceRecipe() {
        FurnaceRecipes.smelting().addSmelting(sponge.blockID, new ItemStack(Item.itemsList[sponge.blockID], 1, 0));
        FurnaceRecipes.smelting().addSmelting(ancientDebris.blockID, new ItemStack(NetheriteItems.netheriteScrap, 1));
        FurnaceRecipes.smelting().addSmelting(deepslateBricks.blockID, new ItemStack(crackedDeepslateBricks, 1));
        FurnaceRecipes.smelting().addSmelting(deepslateTiles.blockID, new ItemStack(crackedDeepslateTiles, 1));
        FurnaceRecipes.smelting().addSmelting(polishedBlackstoneBricks.blockID, new ItemStack(crackedPolishedBlackstoneBricks, 1));
        FurnaceRecipes.smelting().addSmelting(Block.netherBrick.blockID, new ItemStack(crackedNetherBricks, 1));
        FurnaceRecipes.smelting().addSmelting(basalt.blockID, new ItemStack(smoothBasalt, 1));
    }

